sys_script_include.script:
var ServiceDeskIncidentHandler = Class.create();
ServiceDeskIncidentHandler.prototype = {
    initialize: function() {
    },

    /**
     * Creates a new servicedesk_incident record from parsed request body
     * @param {Object} data - parsed JSON body from the REST request
     * @returns {Object} result object with success flag and details
     */
    createIncident: function(data) {
        var result = {};

        try {
            // 1. Requester is mandatory - no point continuing without it
            var requesterSysId = null;
            if (data.requester_email) {
                requesterSysId = this._findUserByEmail(data.requester_email);
            }

            if (!requesterSysId) {
                result.success = false;
                result.error = 'Requester not found for email: ' + data.requester_email;
                return result;
            }

            // 2. Optional fields - assignment group and assigned to.
            // If not found, we just leave them empty and proceed.
            var groupSysId = null;
            if (data.assignment_group) {
                groupSysId = this._findGroupByName(data.assignment_group);
            }

            var assignedToSysId = null;
            if (data.assigned_to_email) {
                assignedToSysId = this._findUserByEmail(data.assigned_to_email);
            }

            // 3. Create the record
            var gr = new GlideRecordSecure('x_1952794_servic_0_servicedesk_incident');
            gr.initialize();

            gr.short_description = data.short_description || '';
            gr.description = data.description || '';
            gr.servicedesk_category = data.category || '';
            gr.servicedesk_subcategory = data.subcategory || '';
            gr.impact = data.impact || '';
            gr.urgency = data.urgency || '';
            gr.external_servicedesk_number = data.external_number || '';
            gr.servicedesk_requester = requesterSysId;

            if (groupSysId) {
                gr.assignment_group = groupSysId;
            }
            if (assignedToSysId) {
                gr.assigned_to = assignedToSysId;
            }

            var newSysId = gr.insert();

            if (newSysId) {
                result.success = true;
                result.sys_id = newSysId;
                result.number = gr.getValue('number');

                // Let the caller know if optional lookups didn't resolve
                var warnings = [];
                if (data.assignment_group && !groupSysId) {
                    warnings.push('Assignment group not found: ' + data.assignment_group);
                }
                if (data.assigned_to_email && !assignedToSysId) {
                    warnings.push('Assigned to user not found: ' + data.assigned_to_email);
                }
                if (warnings.length > 0) {
                    result.warnings = warnings;
                }
            } else {
                result.success = false;
                result.error = 'Insert failed, check field values';
            }

        } catch (ex) {
            result.success = false;
            result.error = ex.getMessage ? ex.getMessage() : ex.toString();
        }

        return result;
    },

    _findUserByEmail: function(email) {
        var userGr = new GlideRecordSecure('sys_user');
        userGr.addQuery('email', email);
        userGr.query();
        if (userGr.next()) {
            return userGr.getUniqueValue();
        }
        return null;
    },

    _findGroupByName: function(name) {
        var groupGr = new GlideRecordSecure('sys_user_group');
        groupGr.addQuery('name', name);
        groupGr.query();
        if (groupGr.next()) {
            return groupGr.getUniqueValue();
        }
        return null;
    },

    type: 'ServiceDeskIncidentHandler'
};
